\caption{\textbf{TACO}: Generative Transfer for EOT with Unknown Cost}
\label{alg:OURMETHOD}
\begin{algorithmic}[1]
\REQUIRE Reference coupling samples $\{(x_i',y_i')\}_{i=1}^n\sim\pi'$;
         new source samples $\{x_i\}_{i=1}^m\sim\mu$, target samples $\{y_j\}_{j=1}^m\sim\nu$;
         step size $\delta=1/N$; noise level $\sigma$.
\STATE \textbf{Pre-train marginal bridges:} Fit CFM models $u_t, v_t$ connecting $(\mu',\mu)$ and $(\nu',\nu)$.
\STATE \textbf{Pre-train reference sampler:} Fit CFM model $\beta_s^0$ on $\pi'$.
\STATE Initialise coupling dataset $\mathcal D_0 \leftarrow \{(x_i',y_i')\}$.
\FOR{$k=0,\ldots,N-1$}
  \STATE \textbf{Train dual potentials $(a_k,b_k)$:} Minimise $\mathcal J_{t_k}$
         in \eqref{eq:energy-ab} via SGD on $\mathcal D_k$.
  \STATE \textbf{Update coupling sampler (Plan A):} Retrain $\beta_s^{k+1}$ with
         importance weights $\exp(\delta(a_k+b_k))$ on $\mathcal D_k$.
  \STATE \textbf{Generate new coupling dataset:} $\mathcal D_{k+1}\leftarrow$
         samples from $\beta_s^{k+1}$.

    \STATE \textbf{Mix particles:} Advance the fixed particle slots ($\alpha$ proportion) by one Euler step along $(u_t,v_t)$; include them in $\mathcal{D}_{k+1}$ alongside the flow samples (breaks circularity; see Appendix~\ref{app:mixed-particle})


\ENDFOR
\ENSURE Coupling sampler $\beta_s^N$ producing approximate samples from $\pi^\star$.
\end{algorithmic}

