We prove both claims for $\mu_t$ (the arguments for $\nu_t$ follow identically).

\noindent\textbf{Log-density is time-Lipschitz:}
Dividing the continuity equation $\partial_t\mu_t + \nabla\cdot(\mu_t u_t)=0$ by $\mu_t > 0$ gives
\begin{equation}
\label{eq:log_density_time_deriv}
\partial_t \log \mu_t = -\nabla \cdot u_t - u_t \cdot \nabla \log \mu_t.
\end{equation}
By Assumption~\ref{ass:velocity_regularity}, $\|\nabla\cdot u_t\|_\infty \le C_{\mathrm{uv}}$ and $\|u_t\|_\infty \le C_{\mathrm{uv}}$.
By Lemma~\ref{lem:density_bounds}, $\|\nabla\log\mu_t\|_\infty \le C_{\mathrm{score}} < \infty$ uniformly in $t$.
Hence $\|\partial_t\log\mu_t\|_\infty \le C_{\mathrm{uv}}(1 + C_{\mathrm{score}}) =: L_{\log}$,
and integrating over time yields the Lipschitz bound.

\noindent\textbf{Score is time-Lipschitz:}
Let $s_t := \nabla\log\mu_t$. Taking the spatial gradient of \eqref{eq:log_density_time_deriv}:
\begin{equation}
\label{eq:score_pde}
\partial_t s_t = -\nabla(\nabla\cdot u_t) - J_{u_t}^T s_t - (\nabla s_t)\,u_t,
\end{equation}
where $J_{u_t}$ is the Jacobian of $u_t$ and $\nabla s_t = \nabla^2\log\mu_t$.
By Assumption~\ref{ass:velocity_regularity} ($u_t \in C^2$ uniformly) and Lemma~\ref{lem:density_bounds} ($\log\mu_t \in C^2$ uniformly), all three terms on the right are bounded, giving $\|\partial_t s_t\|_\infty \le C$ for some uniform $C$. Integrating over time yields the second Lipschitz bound, defining $L_{\mathrm{score}} := \operatorname{ess\,sup}_{t\in[0,1]}\|\partial_t s_t\|_\infty$.

