\label{prop:pot_Lip_time_Linfty}
Under Assumptions \ref{ass:compact_X} to \ref{ass:initial_regularity}, for each $t \in [0,1]$, let $(\varphi_t, \psi_t)$ be the unique relative dual potentials for the target coupling $\pi'$ satisfying the marginal constraints $\mu_t, \nu_t$, under the gauge $\int e^{\psi_t} \, d\nu_t = 1$. Then, there exists a uniform constant $L_{\mathrm{pot}} < \infty$ such that for all $r, t \in [0,1]$:
\begin{equation*}
\|\varphi_r - \varphi_t\|_{L^\infty(\mathcal{X})} + \|\psi_r - \psi_t\|_{L^\infty(\mathcal{X})} \le L_{\mathrm{pot}} |r - t|.
\end{equation*}
The constant $L_{\mathrm{pot}}$ depends only on the target coupling regularity $C_\mathrm{OT}$ and the flow regularity constants $C_\mathrm{uv}, C_{\mu\nu}$.

\begin{equation*}
\|\varphi_r - \varphi_t\|_{L^\infty(\mathcal{X})} + \|\psi_r - \psi_t\|_{L^\infty(\mathcal{X})} \le L_{\mathrm{pot}} |r - t|.
\end{equation*}

The relative dual potentials $(\varphi_t, \psi_t)$ satisfy the coupled Sinkhorn fixed-point equations as \eqref{eq:phipsi_sinkhorn}. We give the proof in two steps.

\noindent\textbf{Stability of the relative Sinkhorn operator:}  By Lemma \ref{lem:temporal_marginal_regularity}, the marginal log-densities are Lipschitz continuous in time. Hence, there exists a uniform constant $L_{\log}$ such that for all $r, t \in [0,1]$:
\begin{equation*}
\label{eq:marg_stability_ref}
\|\log \mu_r - \log \mu_t\|_\infty \le L_{\log} |r - t|, \quad \|\log \nu_r - \log \nu_t\|_\infty \le L_{\log} |r - t|.
\end{equation*}
Let $\mathcal{O}_t$ be the composite operator such that $\psi_t = \mathcal{O}_t(\psi_t)$ defined using Sinkhorn's update \eqref{eq:phipsi_sinkhorn} for a fixed potential $\psi$:
\begin{equation*}
\mathcal{O}_t(\psi)(y) := \log \nu_t(y) - \log \int_{\mathcal{X}} \pi'(x,y) \exp \left( \log \mu_t(x) - \log \int_{\mathcal{X}} \pi'(x,z) e^{\psi(z)} dz \right) dx.
\end{equation*}
To quantify the temporal sensitivity of the operator, define the intermediate function $h(x, t) := \log \mu_t(x) - \log \int \pi'(x,z) e^{\psi(z)} dz$. For any fixed $\psi$, the difference between operators at times $r$ and $t$ satisfies:
\begin{align*}
|\mathcal{O}_r(\psi)(y) - \mathcal{O}_t(\psi)(y)| &\le |\log \nu_r(y) - \log \nu_t(y)| + \left| \log \frac{ \int \pi'(x,y) e^{h(x, r)} dx }{ \int \pi'(x,y) e^{h(x, t)} dx } \right|.
\end{align*}
By the 1-Lipschitz property of the Log-Sum-Exp operator, the second term is bounded by $\|h(\cdot, r) - h(\cdot, t)\|_\infty$. Since $\psi$ is fixed, the integral components in $h$ cancel out, leaving:
\[
\|h(\cdot, r) - h(\cdot, t)\|_\infty = \|\log \mu_r - \log \mu_t\|_\infty.
\]
Combining this with Step 1, the operator perturbation is strictly bounded by:
\begin{equation}
\label{eq:operator_perturbation}
\|\mathcal{O}_r(\psi) - \mathcal{O}_t(\psi)\|_\infty \le 2 L_{\log} |r - t|.
\end{equation}

\noindent\textbf{Uniform contraction and fixed-point sensitivity:} The operator $\mathcal{O}_t$ acts on the space of bounded functions. Under the Hilbert projective metric, the marginals $\mu_t, \nu_t$ act purely as pointwise translations, leaving the contraction rate unaffected. By Birkhoff's Theorem, the contraction ratio $\rho$ of $\mathcal{O}_t$ is determined \textit{exclusively} by the dynamic range of the strictly positive kernel $\pi'(x,y)$:
\begin{equation*}
\rho = \left( \frac{\sqrt{\Delta} - 1}{\sqrt{\Delta} + 1} \right)^2, \quad \text{where } \Delta = \exp\left( \sup_{x,y} \log \pi'(x,y) - \inf_{x,y} \log \pi'(x,y) \right).
\end{equation*}
By Assumption \ref{ass:coupling_regularity}, $\|\log \pi'\|_\infty \le C_\mathrm{OT}$, ensuring that $\Delta < \infty$. Consequently, $\rho < 1$ is a uniform constant for all $t \in [0,1]$. 

Let $\psi_r$ and $\psi_t$ be the fixed points of $\mathcal{O}_r$ and $\mathcal{O}_t$. By \eqref{eq:operator_perturbation}, utilizing the triangle inequality and the uniform contraction property:
\begin{align*}
\|\psi_r - \psi_t\|_\infty &\le \|\mathcal{O}_r(\psi_r) - \mathcal{O}_r(\psi_t)\|_\infty + \|\mathcal{O}_r(\psi_t) - \mathcal{O}_t(\psi_t)\|_\infty \\
&\le \rho \|\psi_r - \psi_t\|_\infty + 2 L_{\log} |r - t|.
\end{align*}
Rearranging yields $\|\psi_r - \psi_t\|_\infty \le \frac{2 L_{\log}}{1 - \rho} |r - t|$. By symmetry, the analogous bound holds for $\|\varphi_r - \varphi_t\|_\infty$. Since each individual potential is Lipschitz with constant $\frac{2L_{\log}}{1-\rho}$, their sum is bounded by $L_{\mathrm{pot}} := \frac{4 L_{\log}}{1 - \rho}$ (twice the individual constant) which completes the proof.

\begin{equation*}
\label{eq:marg_stability_ref}
\|\log \mu_r - \log \mu_t\|_\infty \le L_{\log} |r - t|, \quad \|\log \nu_r - \log \nu_t\|_\infty \le L_{\log} |r - t|.
\end{equation*}

