\end{equation*}

\begin{align*}
|\mathcal{O}_r(\psi)(y) - \mathcal{O}_t(\psi)(y)| &\le |\log \nu_r(y) - \log \nu_t(y)| + \left| \log \frac{ \int \pi'(x,y) e^{h(x, r)} dx }{ \int \pi'(x,y) e^{h(x, t)} dx } \right|.
