(I - S_r T_r)(b_r - b_t) = (\eta_r - \eta_t) - S_r(\zeta_r - \zeta_t) - (S_r - S_t) \zeta_t + S_r(T_r - T_t) b_t + (S_r - S_t) T_t b_t.
\end{equation}
By Lemma \ref{lem:Doeblin_centered_Linfty}, the composite operator $S_r T_r$ is a strict contraction on the $\nu_r$-centered subspace with $\|S_r T_r\| \le 1 - \alpha$. Thus, the operator $(I - S_r T_r)$ is invertible on this subspace, and its inverse is uniformly bounded by $\|(I - S_r T_r)^{-1}\| \le 1/\alpha$. Applying this to \eqref{eq:perturbation_identity} and invoking the non-expansivity $\|S_r\| \le 1$ from Lemma \ref{lem:Doeblin_centered_Linfty}:
\begin{align}
\label{eq:b_diff_expansion}
\|b_r - b_t\|_\infty \le \frac{1}{\alpha} \Big( & \|\eta_r - \eta_t\|_\infty + \|\zeta_r - \zeta_t\|_\infty + \|(S_r - S_t) \zeta_t\|_\infty \nonumber \\
& + \|(T_r - T_t) b_t\|_\infty + \|(S_r - S_t) T_t b_t\|_\infty \Big).
\end{align}
We bound each term in \eqref{eq:b_diff_expansion} using previously established regularities:
\begin{enumerate}[label=(\roman*)]
    \item Forcing terms: By Lemma \ref{lem:forcing_regularity}, $\|\eta_r - \eta_t\|_\infty + \|\zeta_r - \zeta_t\|_\infty \le L_{\mathrm{force}} |r - t|$.
    \item Operator stability on $\zeta_t$: By Lemma \ref{lem:operator_stability_Linfty}, $\|(S_r - S_t) \zeta_t\|_\infty \le L_{\mathrm{op}} \|\zeta_t\|_\infty |r - t| \le L_{\mathrm{op}} C_{\mathrm{force}} |r - t|$.
    \item Operator stability on $b_t$: By Proposition \ref{prop:ab_uniform_Linfty}, $\|b_t\|_\infty \le C_{ab}^\infty$. Thus, $\|(T_r - T_t) b_t\|_\infty \le L_{\mathrm{op}} C_{ab}^\infty |r - t|$.
    \item Composite stability: Since $\|T_t b_t\|_\infty \le \|b_t\|_\infty \le C_{ab}^\infty$, by Lemma \ref{lem:operator_stability_Linfty} and Proposition \ref{prop:ab_uniform_Linfty}, the final term satisfies $\|(S_r - S_t) T_t b_t\|_\infty \le L_{\mathrm{op}} C_{ab}^\infty |r - t|$.
\end{enumerate}
Summing these estimates yields $\|b_r - b_t\|_\infty \le L_b |r - t|$ with $L_b := \frac{1}{\alpha}(L_{\mathrm{force}} + L_{\mathrm{op}} C_{\mathrm{force}} + 2 L_{\mathrm{op}} C_{ab}^\infty)$.
