where $C_2 := 4 C_{ab}^\infty e^{2 C_{ab}^\infty}$ is a uniform constant depending only on the bound $C_{ab}^\infty$.

\begin{equation}
E_{\mathrm{prop}} = \|\bar{\pi}_{t+\delta} - \tilde{\pi}_{t+\delta}\|_{\mathrm{TV}} \le (1 + C_2 \delta) \varepsilon_t,
\end{equation}

Recall that $\bar{\pi}_{t+\delta}$ and $\tilde{\pi}_{t+\delta}$ are obtained by tilting $\pi_t$ and $\tilde{\pi}_t$ respectively with the same frozen weight $\exp(\delta F_t)$. By the definition of the Total Variation distance:
\begin{equation}
\label{eq:prop_tv_start}
2 E_{\mathrm{prop}} = \int_{\mathcal{X}^2} \left| \frac{e^{\delta F_t(x,y)} d\pi_t(x,y)}{\int e^{\delta F_t} d\pi_t} - \frac{e^{\delta F_t(x,y)} d\tilde{\pi}_t(x,y)}{\int e^{\delta F_t} d\tilde{\pi}_t} \right|.
\end{equation}
Using the triangle inequality, the integrand is bounded as:
\begin{align*}
\left| \frac{e^{\delta F_t} d\pi_t}{\int e^{\delta F_t} d\pi_t} - \frac{e^{\delta F_t} d\tilde{\pi}_t}{\int e^{\delta F_t} d\tilde{\pi}_t} \right| \le \underbrace{\frac{e^{\delta F_t}}{\int e^{\delta F_t} d\pi_t} |d\pi_t - d\tilde{\pi}_t|}_{(\mathrm{I})} + \underbrace{e^{\delta F_t} d\tilde{\pi}_t \left| \frac{1}{\int e^{\delta F_t} d\pi_t} - \frac{1}{\int e^{\delta F_t} d\tilde{\pi}_t} \right|}_{(\mathrm{II})}.
\end{align*}
Integrating term $(\mathrm{I})$ over $\mathcal{X}^2$:
\[
\int(\mathrm{I}) \le \frac{\|e^{\delta F_t}\|_\infty}{\int e^{\delta F_t} d\pi_t}\cdot 2\varepsilon_t.
\]
For term $(\mathrm{II})$, write $D_\pi := \int e^{\delta F_t} d\pi_t$ and $D_{\tilde\pi} := \int e^{\delta F_t} d\tilde\pi_t$. Since $\pi_t$ and $\tilde\pi_t$ are both probability measures, $\int 1\,d(\tilde\pi_t - \pi_t) = 0$, so
\[
|D_{\tilde\pi} - D_\pi|
= \left|\int \bigl(e^{\delta F_t}-1\bigr)\,d(\tilde\pi_t-\pi_t)\right|
\le \|e^{\delta F_t}-1\|_\infty \cdot 2\varepsilon_t
\le \bigl(e^{\delta C_{ab}^\infty}-1\bigr)\cdot 2\varepsilon_t.
\]
Hence:
\[
\int(\mathrm{II})
= \frac{|D_{\tilde\pi} - D_\pi|}{D_\pi D_{\tilde\pi}}\int e^{\delta F_t}d\tilde\pi_t
= \frac{|D_{\tilde\pi}-D_\pi|}{D_\pi}
\le \frac{(e^{\delta C_{ab}^\infty}-1)\cdot 2\varepsilon_t}{e^{-\delta C_{ab}^\infty}}
= 2\bigl(e^{2\delta C_{ab}^\infty}-e^{\delta C_{ab}^\infty}\bigr)\varepsilon_t.
\]
Summing both contributions:
\begin{align*}
2 E_{\mathrm{prop}}
\le 2e^{2\delta C_{ab}^\infty}\varepsilon_t + 2\bigl(e^{2\delta C_{ab}^\infty}-e^{\delta C_{ab}^\infty}\bigr)\varepsilon_t
= 2\bigl(2e^{2\delta C_{ab}^\infty}-e^{\delta C_{ab}^\infty}\bigr)\varepsilon_t,
\end{align*}
so $E_{\mathrm{prop}} \le \bigl(2e^{2\delta C_{ab}^\infty}-e^{\delta C_{ab}^\infty}\bigr)\varepsilon_t$.
Note that this bound is tight at $\delta=0$: $2\cdot 1 - 1 = 1$, recovering $E_{\mathrm{prop}} \le \varepsilon_t$ exactly.

Let $f(\delta) := 2e^{2\delta C_{ab}^\infty} - e^{\delta C_{ab}^\infty}$. Then $f(0)=1$ and
$f'(\delta) = 4C_{ab}^\infty e^{2\delta C_{ab}^\infty} - C_{ab}^\infty e^{\delta C_{ab}^\infty} \le 4C_{ab}^\infty e^{2C_{ab}^\infty}$
for $\delta\in[0,1]$. By the mean value theorem, $f(\delta) \le 1 + 4C_{ab}^\infty e^{2C_{ab}^\infty}\,\delta$, so defining $C_2 := 4\,C_{ab}^\infty e^{2C_{ab}^\infty}$:

\begin{equation}
E_{\mathrm{prop}} \le (1 + C_2 \delta)\,\varepsilon_t.
\end{equation}
This completes the proof.

\begin{equation}
\label{eq:prop_tv_start}
2 E_{\mathrm{prop}} = \int_{\mathcal{X}^2} \left| \frac{e^{\delta F_t(x,y)} d\pi_t(x,y)}{\int e^{\delta F_t} d\pi_t} - \frac{e^{\delta F_t(x,y)} d\tilde{\pi}_t(x,y)}{\int e^{\delta F_t} d\tilde{\pi}_t} \right|.
\end{equation}

\begin{align*}
\left| \frac{e^{\delta F_t} d\pi_t}{\int e^{\delta F_t} d\pi_t} - \frac{e^{\delta F_t} d\tilde{\pi}_t}{\int e^{\delta F_t} d\tilde{\pi}_t} \right| \le \underbrace{\frac{e^{\delta F_t}}{\int e^{\delta F_t} d\pi_t} |d\pi_t - d\tilde{\pi}_t|}_{(\mathrm{I})} + \underbrace{e^{\delta F_t} d\tilde{\pi}_t \left| \frac{1}{\int e^{\delta F_t} d\pi_t} - \frac{1}{\int e^{\delta F_t} d\tilde{\pi}_t} \right|}_{(\mathrm{II})}.
\end{align*}

\begin{align*}
2 E_{\mathrm{prop}}
\le 2e^{2\delta C_{ab}^\infty}\varepsilon_t + 2\bigl(e^{2\delta C_{ab}^\infty}-e^{\delta C_{ab}^\infty}\bigr)\varepsilon_t
= 2\bigl(2e^{2\delta C_{ab}^\infty}-e^{\delta C_{ab}^\infty}\bigr)\varepsilon_t,
\end{align*}

\begin{equation}
E_{\mathrm{prop}} \le (1 + C_2 \delta)\,\varepsilon_t.
\end{equation}

\label{cor:error_recursion}
Let $\varepsilon_t = \|\pi_t - \tilde{\pi}_t\|_{\mathrm{TV}}$ be the global coupling error at time $t$. Under the conditions of Lemma \ref{lem:local_error_tv} and Lemma \ref{lem:prop_error_tv}, the error at the next iteration $t+\delta$ satisfies the following linear recurrence:
\begin{equation}
\label{eq:tv_recursion_final}
\varepsilon_{t+\delta} \le (1 + C_2 \delta) \varepsilon_t + C_1 \delta^2,
\end{equation}
where $C_1$ is the local truncation constant and $C_2$ is the error propagation constant.

\begin{equation}
\label{eq:tv_recursion_final}
\varepsilon_{t+\delta} \le (1 + C_2 \delta) \varepsilon_t + C_1 \delta^2,
\end{equation}

Consider the sequence of errors $\{\varepsilon_{t_k}\}_{k=0}^N$ where $t_k = k\delta$. The algorithm is supposed to be initialized with $\tilde{\pi}_0 = \pi_0 = \pi'$ (both coincide with the reference coupling by construction), so $\varepsilon_0 = \|\pi_0 - \tilde{\pi}_0\|_{\mathrm{TV}} = 0$. By iterating the recurrence from Corollary \ref{cor:error_recursion} starting from $\varepsilon_0 = 0$:
\begin{equation*}
\varepsilon_{t_k} \le C_1 \delta^2 \sum_{j=0}^{k-1} (1 + C_2 \delta)^j = C_1 \delta^2 \frac{(1 + C_2 \delta)^k - 1}{(1 + C_2 \delta) - 1}.
\end{equation*}
Simplifying the denominator gives:
\begin{equation*}
\varepsilon_{t_k} \le \frac{C_1 \delta}{C_2} \left[ (1 + C_2 \delta)^k - 1 \right].
\end{equation*}
Using the bound $(1 + C_2 \delta)^k \le e^{k C_2 \delta}$, and setting $k=N=1/\delta$, we obtain:
\begin{equation*}
\varepsilon_1 \le \frac{C_1}{C_2} (e^{C_2} - 1) \delta,
\end{equation*}
which completes the proof.

\begin{equation*}
\varepsilon_{t_k} \le C_1 \delta^2 \sum_{j=0}^{k-1} (1 + C_2 \delta)^j = C_1 \delta^2 \frac{(1 + C_2 \delta)^k - 1}{(1 + C_2 \delta) - 1}.
\end{equation*}

\begin{equation*}
\varepsilon_{t_k} \le \frac{C_1 \delta}{C_2} \left[ (1 + C_2 \delta)^k - 1 \right].
\end{equation*}

\begin{equation*}
\varepsilon_1 \le \frac{C_1}{C_2} (e^{C_2} - 1) \delta,
\end{equation*}

\label{rmk:imperfect_init}
If the algorithm is initialized with a coupling $\tilde{\pi}_0 \ne \pi_0$, so that $\varepsilon_0 := \|\pi_0 - \tilde{\pi}_0\|_{\mathrm{TV}} > 0$, then iterating the recurrence \eqref{eq:tv_recursion_final} from $\varepsilon_0$ yields
\begin{equation*}
    \varepsilon_1 \le e^{C_2}\,\varepsilon_0 + \frac{C_1}{C_2}(e^{C_2} - 1)\,\delta.
\end{equation*}
The first term decays the initialization error at rate $e^{C_2}$ over the full unit interval, while the second term is the same $O(\delta)$ discretization bias as in the perfect-initialization case. Hence, a sub-optimal reference coupling $\pi'$ incurs only a bounded additional error that does not grow with the number of steps.

\begin{equation*}
    \varepsilon_1 \le e^{C_2}\,\varepsilon_0 + \frac{C_1}{C_2}(e^{C_2} - 1)\,\delta.
\end{equation*}

\begin{equation*}
    v_s(z \mid x,y) = (y - x) + \frac{1-2s}{2s(1-s)} \big(z - ((1-s)x + sy)\big) = (y - x) + \frac{1-2s}{2s(1-s)} \big(z - m_s(x, y)\big).
\end{equation*}

\begin{align*}
|\beta_s^t(z) - \tilde{\beta}_s^t(z)|
\le \frac{|\mathcal{N}(\pi_t,e^G) - \mathcal{N}(\tilde{\pi}_t,e^{\bar{G}})|}{\mathcal{D}(\pi_t,e^G)}
+ \frac{C_v(s)\,|\mathcal{D}(\pi_t,e^G) - \mathcal{D}(\tilde{\pi}_t,e^{\bar{G}})|}{\mathcal{D}(\pi_t,e^G)\,\mathcal{D}(\tilde{\pi}_t,e^{\bar{G}})}.
\end{align*}

\begin{align*}
|\mathcal{N}(\pi_t,e^G) - \mathcal{N}(\tilde{\pi}_t,e^{\bar{G}})| &\le
\underbrace{|\mathcal{N}(\pi_t,e^G) - \mathcal{N}(\pi_t,e^{\bar{G}})|}_{\text{weight discrepancy}} +
\underbrace{|\mathcal{N}(\pi_t,e^{\bar{G}}) - \mathcal{N}(\tilde{\pi}_t,e^{\bar{G}})|}_{\text{measure discrepancy}},
\end{align*}

\begin{align*}
|\beta_s^t(z) - \tilde{\beta}_s^t(z)|
&\le \underbrace{\left(\frac{C_v(s)}{\underline{p}(s)} + \frac{C_v(s)}{\underline{p}(s)^2}\right) e^{2\delta C_{ab}^\infty} \cdot \tfrac{1}{2}L_{ab}\delta^2}_{=:\,K_1(s)\,\delta^2}
+ \underbrace{2C_v(s)\!\left(\frac{1}{\underline{p}(s)} + \frac{1}{\underline{p}(s)^2}\right) e^{2\delta C_{ab}^\infty}\,\varepsilon_t}_{=:\,K_2(s)\,\varepsilon_t}.
\end{align*}

\begin{equation}
\label{eq:pointwise_beta_bound}
\|\beta_s^t - \tilde{\beta}_s^t\|_{L^\infty(\mathcal{X})} \le K_1(s)\,\delta^2 + K_2(s)\,C_{\mathrm{global}}\,\delta \le C_\beta(s)\,\delta,
\end{equation}

